// Browser touch input through @rnrs/surface into the Rust touch queue (docs/surface.md, "Touch
// input (browser)"), consumed by the GPU-free touch-probe (packages/fixtures/touch-probe).
// Input comes from driver.mjs as CDP Input.dispatchMouseEvent/dispatchTouchEvent: trusted
// PointerEvents generated by Chromium itself, not hardware. Checks whose names start with
// "SYNTHETIC" dispatch PointerEvent/PageTransitionEvent objects from JS (isTrusted false) for
// cases CDP cannot produce. No timing or latency is measured.
import init, * as wasm from './rnrs/pkg/rnrs_bundle.js';
import { installWebBackend, type RnrsWasm } from '@rnrs/runtime/web';
import { createSurfaceBootstrap } from '@rnrs/surface/browser';
import { createTouchProbeModuleForTesting } from '../../.generated/rnrs/touch_probe';

type Stats = ReturnType<
  ReturnType<ReturnType<typeof createTouchProbeModuleForTesting>['create']>['drain']
>;
type Rec = Stats['recent'][number];
const g = globalThis as any;
const checks: { name: string; ok: boolean; detail: string }[] = [];
const notes: Record<string, unknown> = {};
function assert(value: unknown, message: string): asserts value {
  if (!value) throw new Error(message);
}
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
async function until(what: string, condition: () => boolean, ms = 5000) {
  const end = performance.now() + ms;
  while (!condition()) {
    if (performance.now() > end) throw new Error('timed out: ' + what);
    await sleep(10);
  }
}
let inputId = 0;
type Action = Record<string, unknown>;
/** Real browser input through CDP (driver.mjs); resolves once Chromium dispatched it. */
async function input(...actions: Action[]) {
  const id = ++inputId;
  g.__touchInput = { id, actions };
  await until('CDP input ' + id, () => g.__touchInputDone === id);
}
const mouse = (type: string, x: number, y: number, buttons = 0, extra: Action = {}) => ({
  kind: 'mouse',
  type,
  x,
  y,
  buttons,
  ...extra,
});
const touch = (type: string, points: { x: number; y: number; id: number }[] = []) => ({
  kind: 'touch',
  type,
  points,
});
const metrics = (dpr: number) => ({ kind: 'metrics', dpr });
const counters = (key: number) => Array.from(wasm.rnrs_surface_touch_counters(key)) as number[];
const diagnostics = () => Array.from(wasm.rnrs_surface_diagnostics()) as number[];

// The surface element: 200x100 CSS px at (20, 40).
const LEFT = 20,
  TOP = 40;
function setup(touchInput: 'none' | 'rust' = 'rust') {
  let boot!: ReturnType<typeof createSurfaceBootstrap>;
  const backend = installWebBackend(
    wasm as unknown as RnrsWasm,
    (same) => (boot = createSurfaceBootstrap(same)),
  );
  const module = createTouchProbeModuleForTesting(8);
  const probe = module.create();
  const key = probe.surfaceKey();
  const wrapper = document.createElement('div'),
    canvas = document.createElement('canvas');
  wrapper.style.cssText = `position:absolute;left:${LEFT}px;top:${TOP}px;width:200px;height:100px`;
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  wrapper.append(canvas);
  document.body.append(wrapper);
  const errors: string[] = [];
  const mount = boot.host.mount(canvas, wrapper, key, (e) => errors.push(String(e)));
  if (touchInput === 'rust') mount.setTouchInput('rust');
  const ids: number[] = []; // pointerIds of pointerdowns seen by the page (for synthetic events)
  wrapper.addEventListener('pointerdown', (e) => ids.push(e.pointerId));
  let base = probe.drain();
  return {
    backend,
    boot,
    module,
    probe,
    key,
    wrapper,
    canvas,
    errors,
    mount,
    ids,
    /** Drains; returns the records since the previous call (at most 32). */
    take() {
      const s = probe.drain();
      const n = s.records - base.records;
      assert(n <= 32, 'too many records for one check: ' + n);
      const recs = n ? s.recent.slice(-n) : [];
      base = s;
      return { s, recs };
    },
    async attached(width = 200 * devicePixelRatio) {
      await until('attached at ' + width, () => {
        const s = probe.drain();
        return s.state === 'attached' && s.surfaceWidth === width;
      });
    },
    cleanup() {
      try {
        mount.dispose();
      } catch {}
      try {
        probe.close();
      } catch {}
      backend.dispose();
      wrapper.remove();
    },
  };
}
type H = ReturnType<typeof setup>;
async function test(
  name: string,
  run: (h: H) => Promise<void>,
  touchInput: 'none' | 'rust' = 'rust',
) {
  const h = setup(touchInput);
  try {
    await run(h);
    assert(h.errors.length === 0, 'host errors: ' + h.errors.join('; '));
    checks.push({ name, ok: true, detail: '' });
  } catch (error) {
    checks.push({ name, ok: false, detail: String(error) });
  } finally {
    try {
      h.cleanup();
    } catch (error) {
      checks.push({ name: name + ' cleanup', ok: false, detail: String(error) });
    }
    const d = diagnostics();
    if (d[1] || d[3])
      checks.push({
        name: name + ' producer slots released',
        ok: false,
        detail: JSON.stringify(d),
      });
  }
}
const kinds = (recs: Rec[]) => recs.map((r) => r.kind + (r.reason ? ':' + r.reason : '')).join(',');
const clean = (s: Stats) => {
  assert(s.contradictions === 0, 'contradiction: ' + s.lastContradiction);
  assert(s.down.length === 0, 'pointers left down: ' + s.down.length);
};
const at = (r: Rec, x: number, y: number) =>
  Math.abs(r.xPx - x) < 0.01 && Math.abs(r.yPx - y) < 0.01;
const where = (r: Rec) => `${r.kind} (${r.xPx}, ${r.yPx}) in ${r.width}x${r.height}@${r.scale}`;

async function run() {
  await test('real mouse (CDP): primary-button drag is down/move/up in element-local physical px', async (h) => {
    await h.attached(200);
    await input(
      mouse('mousePressed', LEFT + 50, TOP + 25, 1),
      mouse('mouseMoved', LEFT + 100, TOP + 25, 1),
      mouse('mouseMoved', LEFT + 110, TOP + 30, 1),
      mouse('mouseReleased', LEFT + 110, TOP + 30),
    );
    const { s, recs } = h.take();
    assert(kinds(recs) === 'down,move,up', 'records: ' + kinds(recs));
    assert(
      at(recs[0], 50, 25) && at(recs[1], 110, 30) && at(recs[2], 110, 30),
      'positions: ' + recs.map(where).join('; '),
    );
    assert(
      recs.every(
        (r) =>
          r.width === 200 && r.height === 100 && r.scale === 1 && r.attachment === s.attachment,
      ),
      'extent/attachment: ' + recs.map(where).join('; '),
    );
    assert(
      recs[0].timeMs > 0 &&
        recs[2].timeMs >= recs[0].timeMs &&
        recs[2].timeMs <= performance.now() + 1,
      'event time base is performance.now ms',
    );
    assert(s.coalesced >= 1, 'consecutive moves coalesced in the queue');
    clean(s);
    await input(
      mouse('mouseMoved', LEFT + 60, TOP + 20),
      mouse('mousePressed', LEFT + 60, TOP + 20, 2, { button: 'right' }),
      mouse('mouseMoved', LEFT + 70, TOP + 20, 2),
      mouse('mouseReleased', LEFT + 70, TOP + 20, 0, { button: 'right' }),
      mouse('mousePressed', LEFT + 60, TOP + 20, 1, { pointerType: 'pen' }),
      mouse('mouseMoved', LEFT + 70, TOP + 20, 1, { pointerType: 'pen' }),
      mouse('mouseReleased', LEFT + 70, TOP + 20, 0, { pointerType: 'pen' }),
    );
    const after = h.take();
    assert(
      after.recs.length === 0 && after.s.accepted === s.accepted,
      'hover, secondary button and pen are not delivered: ' + kinds(after.recs),
    );
  });

  await test('real mouse (CDP): pointer capture keeps the gesture outside the element', async (h) => {
    await h.attached(200);
    await input(
      mouse('mousePressed', LEFT + 10, TOP + 10, 1),
      mouse('mouseMoved', LEFT + 380, TOP + 260, 1),
      mouse('mouseReleased', LEFT + 380, TOP + 260),
    );
    const { s, recs } = h.take();
    assert(
      kinds(recs) === 'down,move,up' && at(recs[1], 380, 260) && at(recs[2], 380, 260),
      'records: ' + recs.map(where).join('; '),
    );
    clean(s);
  });

  await test('real touch (CDP) at devicePixelRatio 2: two pointers with stable ids, real touchCancel is a cancel', async (h) => {
    await input({ kind: 'touchEmulation' }, metrics(2));
    await until('dpr 2', () => devicePixelRatio === 2);
    await h.attached(400);
    const A = (x: number, y: number) => ({ x: LEFT + x, y: TOP + y, id: 1 }),
      B = (x: number, y: number) => ({ x: LEFT + x, y: TOP + y, id: 2 });
    await input(
      touch('touchStart', [A(20, 10)]),
      touch('touchStart', [A(20, 10), B(90, 40)]),
      touch('touchMove', [A(25, 12), B(95, 45)]),
      touch('touchEnd'),
    );
    const { s, recs } = h.take();
    assert(kinds(recs) === 'down,down,move,move,up,up', 'records: ' + kinds(recs));
    assert(
      at(recs[0], 40, 20) && at(recs[1], 180, 80),
      'physical px = 2 x CSS px: ' + recs.map(where).join('; '),
    );
    assert(
      recs[0].id !== recs[1].id &&
        recs.every((r) => r.width === 400 && r.height === 200 && r.scale === 2),
      'ids/extent: ' + recs.map(where).join('; '),
    );
    clean(s);
    await input(touch('touchStart', [A(30, 30)]), touch('touchCancel'));
    const canceled = h.take();
    assert(kinds(canceled.recs) === 'down,cancel', 'touchCancel: ' + kinds(canceled.recs));
    clean(canceled.s);
    notes.touchIds = recs.map((r) => r.id);
    await input(metrics(1));
    await until('dpr 1', () => devicePixelRatio === 1);
  });

  await test('real touch (CDP): resize mid-gesture; later events carry the new extent', async (h) => {
    await h.attached(200);
    const A = (x: number, y: number) => [{ x: LEFT + x, y: TOP + y, id: 1 }];
    await input(touch('touchStart', A(20, 10)));
    h.wrapper.style.width = '300px';
    await h.attached(300);
    await input(touch('touchMove', A(290, 10)), touch('touchEnd'));
    const { s, recs } = h.take();
    assert(
      kinds(recs) === 'down,move,up' &&
        recs[0].width === 200 &&
        at(recs[1], 290, 10) &&
        recs[1].width === 300,
      'records: ' + recs.map(where).join('; '),
    );
    clean(s);
  });

  await test('real touch (CDP): a burst over the 128-record queue overflows into one reset, nothing left down', async (h) => {
    await h.attached(200);
    const actions: Action[] = [];
    for (let i = 0; i < 70; i++)
      actions.push(touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]), touch('touchEnd'));
    await input(...actions);
    const c = counters(h.key);
    const s = h.probe.drain();
    assert(
      s.overflows === 1 && s.resetsOverflow === 1,
      `overflow ${s.overflows}, resets ${s.resetsOverflow}`,
    );
    assert(s.records <= 128, 'one drain is bounded: ' + s.records);
    assert(c[7] === 0, 'no pointer down on the producer side');
    clean(s);
  });

  await test(
    'opt-out (default "none"): no listeners, no touch-action, no preventDefault, nothing reaches Rust',
    async (h) => {
      await h.attached(200);
      assert(
        h.wrapper.style.touchAction === '',
        'touch-action untouched: ' + h.wrapper.style.touchAction,
      );
      await input(
        mouse('mousePressed', LEFT + 50, TOP + 25, 1),
        mouse('mouseReleased', LEFT + 50, TOP + 25),
        touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]),
        touch('touchEnd'),
      );
      const down = new PointerEvent('pointerdown', {
        pointerId: 77,
        pointerType: 'touch',
        clientX: LEFT + 5,
        clientY: TOP + 5,
        cancelable: true,
        bubbles: true,
      });
      h.canvas.dispatchEvent(down); // SYNTHETIC
      const { s, recs } = h.take();
      assert(
        recs.length === 0 && s.accepted === 0 && s.refusedStale === 0,
        'nothing pushed: ' + kinds(recs),
      );
      assert(!down.defaultPrevented, 'default not prevented');
    },
    'none',
  );

  await test('real mouse (CDP): releasing the primary button while the secondary is held ends the pointer', async (h) => {
    await h.attached(200);
    await input(
      mouse('mousePressed', LEFT + 50, TOP + 25, 1),
      mouse('mousePressed', LEFT + 50, TOP + 25, 3, { button: 'right' }),
      mouse('mouseMoved', LEFT + 60, TOP + 25, 3),
      mouse('mouseReleased', LEFT + 60, TOP + 25, 2),
      mouse('mouseMoved', LEFT + 70, TOP + 25, 2),
      mouse('mouseReleased', LEFT + 70, TOP + 25, 0, { button: 'right' }),
    );
    const { s, recs } = h.take();
    assert(
      kinds(recs) === 'down,move,up' && at(recs[2], 60, 25),
      'records: ' + recs.map(where).join('; '),
    );
    assert(s.producerDown === 0, 'nothing down on the producer side');
    clean(s);
  });

  await test('SYNTHETIC events: a failed pointer capture cancels the accepted down; pointercancel and lostpointercapture cancel', async (h) => {
    await h.attached(200);
    // No active pointer 77, so setPointerCapture throws NotFoundError.
    const down = new PointerEvent('pointerdown', {
      pointerId: 77,
      pointerType: 'touch',
      clientX: LEFT + 5,
      clientY: TOP + 5,
      cancelable: true,
      bubbles: true,
    });
    h.canvas.dispatchEvent(down);
    let { s, recs } = h.take();
    assert(
      kinds(recs) === 'down,cancel' && s.producerDown === 0,
      'capture failure: ' + kinds(recs),
    );
    assert(!down.defaultPrevented, 'a pointer not taken is not prevented');
    assert(
      h.errors.length === 1 && /NotFound/.test(h.errors[0]),
      'reported once: ' + h.errors.join('; '),
    );
    h.errors.length = 0;
    clean(s);
    // A real down is taken: its default is prevented (seen by a later bubbling listener).
    let prevented: boolean | undefined;
    const seen = (e: Event) => {
      prevented = e.defaultPrevented;
    };
    document.addEventListener('pointerdown', seen);
    await input(touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]));
    document.removeEventListener('pointerdown', seen);
    assert(prevented === true, 'accepted real down prevents default');
    h.wrapper.dispatchEvent(
      new PointerEvent('pointercancel', {
        pointerId: h.ids[h.ids.length - 1],
        pointerType: 'touch',
      }),
    );
    await input(touch('touchEnd'));
    ({ s, recs } = h.take());
    assert(kinds(recs) === 'down,cancel', 'synthetic pointercancel: ' + kinds(recs));
    clean(s);
    // A real touch whose capture is reported lost (synthetic lostpointercapture) is canceled; its
    // real end afterwards is ignored.
    await input(touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]));
    const id = h.ids[h.ids.length - 1];
    h.wrapper.dispatchEvent(
      new PointerEvent('lostpointercapture', { pointerId: id, pointerType: 'touch' }),
    );
    await input(touch('touchMove', [{ x: LEFT + 60, y: TOP + 50, id: 1 }]), touch('touchEnd'));
    ({ s, recs } = h.take());
    assert(kinds(recs) === 'down,cancel', 'lostpointercapture: ' + kinds(recs));
    clean(s);
  });

  await test('opting out mid-gesture cancels all held pointers and removes listeners and touch-action', async (h) => {
    await h.attached(200);
    assert(h.wrapper.style.touchAction === 'none', 'touch-action set while opted in');
    await input(touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]));
    h.mount.setTouchInput('none');
    assert(h.wrapper.style.touchAction === '', 'touch-action restored');
    await input(touch('touchMove', [{ x: LEFT + 60, y: TOP + 50, id: 1 }]), touch('touchEnd'));
    const { s, recs } = h.take();
    assert(kinds(recs) === 'down,cancel', 'records: ' + kinds(recs));
    assert(s.refusedStale === 0, 'later events not pushed at all');
    clean(s);
  });

  await test('unmount mid-gesture: detach queues a reset; later events are not delivered', async (h) => {
    await h.attached(200);
    await input(touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]));
    h.mount.dispose();
    await input(touch('touchMove', [{ x: LEFT + 60, y: TOP + 50, id: 1 }]), touch('touchEnd'));
    const { s, recs } = h.take();
    assert(
      kinds(recs) === 'down,reset:detached' && s.state === 'detached',
      'records: ' + kinds(recs) + ' ' + s.state,
    );
    clean(s);
  });

  await test('SYNTHETIC pagehide/pageshow mid-gesture: reset, old pointer ignored, new attachment starts clean', async (h) => {
    await h.attached(200);
    await input(touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]));
    const first = h.probe.drain().attachment; // drain() does not reset take()'s window
    window.dispatchEvent(new PageTransitionEvent('pagehide'));
    await input(touch('touchMove', [{ x: LEFT + 60, y: TOP + 50, id: 1 }]));
    window.dispatchEvent(new PageTransitionEvent('pageshow'));
    await h.attached(200);
    await input(
      touch('touchMove', [{ x: LEFT + 70, y: TOP + 50, id: 1 }]),
      touch('touchEnd'),
      touch('touchStart', [{ x: LEFT + 10, y: TOP + 10, id: 1 }]),
      touch('touchEnd'),
    );
    const { s, recs } = h.take();
    assert(kinds(recs) === 'down,reset:detached,down,up', 'records: ' + kinds(recs));
    const last = recs.slice(-2);
    assert(
      last.every((r) => r.attachment > first),
      'new attachment ' + last.map((r) => r.attachment) + ' after ' + first,
    );
    clean(s);
  });

  await test('runtime replacement mid-gesture: host disposal resets the queue, a new runtime takes input', async (h) => {
    await h.attached(200);
    await input(touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]));
    const before = counters(h.key);
    assert(before[7] === 1, 'one pointer down before replacement');
    h.backend.dispose(); // retires the host (detach: reset) and tears down the probe's runtime
    const after = counters(h.key);
    assert(
      after.length === 0 || (after[6] > before[6] && after[7] === 0),
      'reset queued, none down: ' + JSON.stringify([before, after]),
    );
    await input(touch('touchMove', [{ x: LEFT + 60, y: TOP + 50, id: 1 }]), touch('touchEnd'));
    const next = setup('rust');
    try {
      await next.attached(200);
      await input(touch('touchStart', [{ x: LEFT + 50, y: TOP + 50, id: 1 }]), touch('touchEnd'));
      const { s, recs } = next.take();
      assert(kinds(recs) === 'down,up', 'new runtime: ' + kinds(recs));
      clean(s);
    } finally {
      next.cleanup();
    }
  });
}

async function main() {
  await init({ module_or_path: new URL('../rnrs/pkg/rnrs_bundle_bg.wasm', import.meta.url) });
  notes.userAgent = navigator.userAgent;
  await run();
}
main()
  .catch((error) => checks.push({ name: 'main', ok: false, detail: String(error) }))
  .finally(() => {
    const ok = checks.length > 0 && checks.every((c) => c.ok);
    g.__rnrsResult = {
      ok,
      checks,
      notes,
      label:
        'headless Chromium (--disable-gpu); CDP Input.* pointer input (trusted, browser-generated, not hardware); ' +
        'checks named SYNTHETIC use JS-dispatched events; no latency measured',
    };
    document.getElementById('out')!.textContent = JSON.stringify(g.__rnrsResult, null, 2);
  });
